#include "../RahiTuber/MaxPlushMath.h"
#include <stdexcept>
#include <iostream>
int main(){for(float yaw:{-180.f,-90.f,-45.f,0.f,45.f,90.f,180.f})for(float depth:{.05f,.45f,1.25f})for(float u:{-1.f,1.f})if(std::fabs(MaxPlushX(100,80,u,depth,yaw,false)-MaxPlushX(100,80,u,depth,yaw,true))>.001f)throw std::runtime_error("Front and back seams separated");if(!MaxPlushFacing(0,.45f,0,false)||MaxPlushFacing(0,.45f,0,true)||!MaxPlushFacing(0,.45f,180,true))throw std::runtime_error("Wrong face shown");unsigned char image[4*4*4]={};image[(1*4+1)*4+3]=1;image[(1*4+2)*4+3]=255;auto contour=MaxPlushContour(image,4,4,0,0,4,4);if(contour[0].valid||!contour[1].valid||contour[1].left!=1||contour[1].right!=3)throw std::runtime_error("Transparent contour lost antialias edge");for(float yaw:{-179.f,-135.f,-90.f,-45.f,0.f,45.f,90.f,135.f,179.f})for(bool rear:{false,true}){auto arc=MaxPlushVisibleArc(.45f,yaw,rear);if(!arc.valid)continue;float last=MaxPlushX(100,80,-std::cos(arc.begin),.45f,yaw,rear);for(int i=1;i<=96;i++){float x=MaxPlushX(100,80,-std::cos(arc.begin+(arc.end-arc.begin)*i/96),.45f,yaw,rear);if((rear?last-x:x-last)<-.001f)throw std::runtime_error("Surface folds at a turn angle");last=x;}}
 if(std::fabs(MaxPlushDragAngle(170,120,240)+10)>.01f)throw std::runtime_error("Manual spin does not wrap correctly");std::cout<<"PASS: shared seams at every turn, facing and transparent contours\n";}
